import{_ as e,o as r,c as t,ag as i}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"欢迎来到 Unciv！","description":"","frontmatter":{},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),n={name:"zh/index.md"};function c(h,a,o,s,l,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="欢迎来到-unciv" tabindex="-1">欢迎来到 Unciv！ <a class="header-anchor" href="#欢迎来到-unciv" aria-label="Permalink to &quot;欢迎来到 Unciv！&quot;">​</a></h1><p><img src="https://raw.githubusercontent.com/yairm210/Unciv/master/extraImages/GithubPreviewImage.jpg" alt="image"></p><p><a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">Unciv</a> 是一个开源的、模组友好的《文明5》安卓和桌面复刻版，使用 LibGDX 制作。建立你的文明，研究科技，扩张你的城市，击败你的敌人！</p><h2 id="如何游玩" tabindex="-1">如何游玩？ <a class="header-anchor" href="#如何游玩" aria-label="Permalink to &quot;如何游玩？&quot;">​</a></h2><p>原版玩法与《文明5》一致，任何《文明5》攻略都适用。</p><p>游戏内置教程帮助你上手。</p><h2 id="如何贡献" tabindex="-1">如何贡献？ <a class="header-anchor" href="#如何贡献" aria-label="Permalink to &quot;如何贡献？&quot;">​</a></h2><p>参与社区是第一步：加入 <a href="https://discord.gg/bjrB4Xw" target="_blank" rel="noreferrer">Discord！</a> 这是结识其他贡献者的好地方。</p><p>此外，你可以在仓库的 <a href="https://github.com/yairm210/Unciv/issues" target="_blank" rel="noreferrer">Issue Tracker</a> 跟踪请求、bug 和待办事项。</p><p>如果你是开发者，可以从 <a href="/Unciv/zh/Developers/Building-Locally.html">入门指南</a> 开始！</p><p>如果你是翻译者，前往 <a href="/Unciv/zh/Translating/Translating.html">翻译！</a></p><p>如果你是模组制作者，<a href="/Unciv/zh/Modders/Mods.html">从这里开始</a>。</p><p>如果你不是以上角色，你仍然可以通过传播来帮助——在你能投票的地方给 Unciv 投票，在 Reddit 或 Twitter 等处提及它，并帮助我们想出新的宣传点子！</p><h2 id="uncivcn-专区" tabindex="-1">UncivCN 专区 <a class="header-anchor" href="#uncivcn-专区" aria-label="Permalink to &quot;UncivCN 专区&quot;">​</a></h2><p>本站是 UncivCN 分支的文档站：英文区复用上游文档，中文区为完整翻译镜像。中文独有的内容（分支特性、社区攻略、模组专区、更新日志等）统一收录在 <a href="/Unciv/zh/UncivCN/">UncivCN 专区</a>。</p>',15)])])}const u=e(n,[["render",c]]);export{m as __pageData,u as default};
